{!REQUIRESCRIPT("/soap/ajax/30.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/30.0/apex.js")}

var qry= sforce.connection.query("SELECT id,name,Order__c,Order__r.Account__r.id from Order_Line_Item__c where Order__c='{!OrderC__c.Id}'");


var xcd= sforce.connection.query("SELECT id,name,Created_For_Account__c,Order_Custom__c from Xcode__c where Created_For_Account__c='{!OrderC__c.Acct_SF_Id__c}'");

//Added By Vimal Srivastava to prevent Verified/Closed/Negated/Rejected order TCS Jan 11 2018
if(  "{!OrderC__c.OrderStatus__c}" == "Verified" || "{!OrderC__c.OrderStatus__c}" == "Closed" || "{!OrderC__c.OrderStatus__c}" == "Negated" || "{!OrderC__c.OrderStatus__c}" == "Rejected"){
alert("Order is alreay in Verified/Closed/Negated/Rejected status can not be sent to varification.");
}

else{

if(qry.size == 0){
alert("An Error has occurred. Please make sure that there is at least one Order line item");

}

else{

if(xcd.size == 0){
alert('Error: XCode is required on (all) Order Line Item(s).'); 
}
else{
alert("verified successfully");
var newRecords = []; 
var c = new sforce.SObject("OrderC__c");
c.ID = '{!OrderC__c.Id}';
c.OrderStatus__c = "Verified";

newRecords.push(c); 
var  result = sforce.connection.update(newRecords); 

var oid='{!OrderC__c.Id}';
var ord =sforce.apex.execute("CaptureOrderVfDateTime","ORderVerfiCatcher",{Ids:oid});
window.location.reload(); 
}
}

}
